"""Install root agent launcher shims and shell shortcut.

Writes ``agent.ps1`` (Windows) and ``agent.sh`` (POSIX) to the estate code root
(``C:\\code`` or ``~/code``). The shim runs ``rig agent`` on the C# CLI in this checkout
(``dotnet run --project src/Rig.Cli``) with passthrough arguments.
"""

from __future__ import annotations

import sys
from pathlib import Path

from rich.console import Console

from rig import roots

from .agent_shortcut import configure_agent_shortcut

console = Console()

SHIM_HEADER = (
    "# Generated by `devenv setup`. Do not edit by hand.\n"
    "# Launches your preferred AI coding agent or selected flag (-agy, -ccc, -agywsl, -dng)."
)


def get_canonical_project_root() -> Path:
    """Return the root of personal/shared-utilities, resolving outside of any worktree."""
    current = Path(__file__).resolve()
    for parent in current.parents:
        if parent.name == ".worktrees":
            return parent.parent
        if (parent / "pyproject.toml").is_file():
            if parent.parent.name == ".worktrees":
                return parent.parent.parent
            return parent

    if sys.platform == "win32":
        return Path("C:/code/personal/shared-utilities")
    return Path.home() / "code" / "personal" / "shared-utilities"


def get_estate_root(project_root: Path | None = None) -> Path:
    """Return the estate code root (e.g. C:\\code or ~/code)."""
    proj = project_root or get_canonical_project_root()
    found = roots.find_code_root(proj)
    if found is not None:
        return found
    return proj.parent.parent if proj.parent.name == "personal" else proj.parent


def generate_ps1_content(project_root: Path) -> str:
    """Generate the body for agent.ps1."""
    cli = str(project_root / "src" / "Rig.Cli")
    return f"""{SHIM_HEADER}
dotnet run --project "{cli}" -- agent @args
exit $LASTEXITCODE
"""


def generate_sh_content(project_root: Path) -> str:
    """Generate the body for agent.sh."""
    cli = (project_root / "src" / "Rig.Cli").as_posix()
    return f"""#!/usr/bin/env bash
{SHIM_HEADER}
exec dotnet run --project "{cli}" -- agent "$@"
"""


def install_agent_launcher(
    *,
    project_root: Path | None = None,
    estate_root: Path | None = None,
    dry_run: bool = False,
) -> Path:
    """Write agent.ps1 and agent.sh to the estate code root."""
    proj = project_root or get_canonical_project_root()
    estate = estate_root or get_estate_root(proj)

    ps1_path = estate / "agent.ps1"
    sh_path = estate / "agent.sh"

    ps1_content = generate_ps1_content(proj)
    sh_content = generate_sh_content(proj)

    if dry_run:
        console.print(f"[dim][dry-run] Would write agent launcher shim to {estate}[/dim]")
        return ps1_path if sys.platform == "win32" else sh_path

    estate.mkdir(parents=True, exist_ok=True)
    if sys.platform == "win32":
        ps1_path.write_text(ps1_content, encoding="utf-8")
        sh_path.write_text(sh_content, encoding="utf-8")
        console.print(f"[bold green]OK: Agent launcher shims ready in {estate}[/bold green]")
        return ps1_path

    sh_path.write_text(sh_content, encoding="utf-8")
    sh_path.chmod(0o755)
    console.print(f"[bold green]OK: Agent launcher shim ready: {sh_path}[/bold green]")
    return sh_path


def setup_agent_launcher(
    *,
    project_root: Path | None = None,
    estate_root: Path | None = None,
    profile_path: Path | None = None,
    dry_run: bool = False,
) -> bool:
    """Install the estate root shim and configure the shell shortcut."""
    shim = install_agent_launcher(project_root=project_root, estate_root=estate_root, dry_run=dry_run)
    return configure_agent_shortcut(shim, profile_path=profile_path, dry_run=dry_run)
